from types import GeneratorType
from typing import Any, Callable, Dict, Iterable, Iterator

import pandas as pd

from ..utils import chunk, get_axis_int
from .generic import DataType

# `DataFrame.applymap` is deprecated since pandas 2.1.0 in favor of `DataFrame.map`.
# Both have the exact same semantic, so use the non deprecated one when available in
# order not to pollute the user output with deprecation warnings.
_APPLYMAP_METHOD_NAME = "map" if hasattr(pd.DataFrame, "map") else "applymap"


class DataFrame:
    class Apply(DataType):
        @staticmethod
        def get_chunks(
            nb_workers: int, data: pd.DataFrame, **kwargs
        ) -> Iterator[pd.DataFrame]:
            user_defined_function_kwargs = kwargs["user_defined_function_kwargs"]

            axis_int = get_axis_int(user_defined_function_kwargs)
            opposite_axis_int = 1 - axis_int

            for chunk_ in chunk(data.shape[opposite_axis_int], nb_workers):
                yield data.iloc[chunk_] if axis_int == 1 else data.iloc[:, chunk_]

        @staticmethod
        def work(
            data: pd.DataFrame,
            user_defined_function: Callable,
            user_defined_function_args: tuple,
            user_defined_function_kwargs: Dict[str, Any],
            extra: Dict[str, Any],
        ) -> pd.DataFrame:
            return data.apply(
                user_defined_function,
                *user_defined_function_args,
                **user_defined_function_kwargs,
            )

        @staticmethod
        def get_reduce_extra(
            data: Any, user_defined_function_kwargs: Dict[str, Any]
        ) -> Dict[str, Any]:
            return {"axis": get_axis_int(user_defined_function_kwargs)}

        @staticmethod
        def reduce(
            datas: Iterable[pd.DataFrame], extra: Dict[str, Any]
        ) -> pd.DataFrame:
            if isinstance(datas, GeneratorType):
                datas = list(datas)
            else:
                datas = list(datas)

            axis = 0 if isinstance(datas[0], pd.Series) else 1 - extra["axis"]
            return pd.concat(datas, copy=False, axis=axis)

    class ApplyMap(DataType):
        @staticmethod
        def get_chunks(
            nb_workers: int, data: pd.DataFrame, **kwargs
        ) -> Iterator[pd.DataFrame]:
            for chunk_ in chunk(data.shape[0], nb_workers):
                yield data.iloc[chunk_]

        @staticmethod
        def work(
            data: pd.DataFrame,
            user_defined_function: Callable,
            user_defined_function_args: tuple,
            user_defined_function_kwargs: Dict[str, Any],
            extra: Dict[str, Any],
        ) -> pd.DataFrame:
            applymap = getattr(data, _APPLYMAP_METHOD_NAME)
            return applymap(user_defined_function, **user_defined_function_kwargs)

        @staticmethod
        def reduce(
            datas: Iterable[pd.DataFrame], extra: Dict[str, Any]
        ) -> pd.DataFrame:
            return pd.concat(datas, copy=False)

from abc import ABC, abstractmethod
from typing import Any, Callable, Dict, Iterable, Iterator


class DataType(ABC):
    """Describe how a given pandas data type is split, computed and merged back.

    Each supported pandas object (``DataFrame``, ``Series``, ``DataFrameGroupBy``,
    ``Rolling``, ``RollingGroupby``, ``ExpandingGroupby``, ...) provides an
    implementation of this interface:

    - ``get_chunks``: split the data into ``nb_workers`` chunks (map step),
    - ``work``: what a single worker computes on a single chunk,
    - ``reduce``: how the chunk results are merged back into a single object.
    """

    @staticmethod
    @abstractmethod
    def get_chunks(nb_workers: int, data: Any, **kwargs) -> Iterator[Any]:
        ...

    @staticmethod
    def get_work_extra(data: Any) -> Dict[str, Any]:
        return dict()

    @staticmethod
    @abstractmethod
    def work(
        data: Any,
        user_defined_function: Callable,
        user_defined_function_args: tuple,
        user_defined_function_kwargs: Dict[str, Any],
        extra: Dict[str, Any],
    ) -> Any:
        ...

    @staticmethod
    def get_reduce_extra(
        data: Any, user_defined_function_kwargs: Dict[str, Any]
    ) -> Dict[str, Any]:
        return dict()

    @staticmethod
    @abstractmethod
    def reduce(datas: Iterable[Any], extra: Dict[str, Any]) -> Any:
        ...

