from typing import Any, Callable, Dict, Iterable, Iterator

import pandas as pd
from pandas.core.window.expanding import Expanding
from pandas.core.window.rolling import Rolling

from ..utils import chunk, get_window_attributes
from .generic import DataType


def can_be_chunked(attributes: Dict[str, Any]) -> bool:
    """Return whether a rolling window can safely be computed chunk by chunk.

    A chunk is extended on its left by ``window`` items, so its own items are computed
    with the exact same data as in the sequential case. This trick only works if:

    - the window is expressed as a fixed number of items (an offset based window, like
      ``"2s"``, would need a time based left extension),
    - the window is not centered (a centered window also needs data on its right),
    - the window is not strided (``step``), since strides are computed from the
      beginning of the data.

    When one of these conditions is not met, the computation is done by a single worker
    so the result stays correct.
    """
    if attributes.get("center", False):
        return False

    if attributes.get("step", None) not in (None, 1):
        return False

    window = attributes.get("window", None)

    return isinstance(window, int) and not isinstance(window, bool)


class SeriesRolling:
    class Apply(DataType):
        @staticmethod
        def get_chunks(
            nb_workers: int, rolling: Rolling, **kwargs
        ) -> Iterator[pd.Series]:
            attributes = get_window_attributes(rolling)

            if not can_be_chunked(attributes):
                yield rolling.obj
                return

            chunks = chunk(len(rolling.obj), nb_workers, attributes["window"])

            for chunk_ in chunks:
                yield rolling.obj.iloc[chunk_]

        @staticmethod
        def get_work_extra(data: Rolling) -> Dict[str, Any]:
            return {"attributes": get_window_attributes(data)}

        @staticmethod
        def work(
            data: pd.Series,
            user_defined_function: Callable,
            user_defined_function_args: tuple,
            user_defined_function_kwargs: Dict[str, Any],
            extra: Dict[str, Any],
        ) -> pd.Series:
            attributes: Dict[str, Any] = extra["attributes"]
            worker_index: int = extra["worker_index"]

            result = data.rolling(**attributes).apply(
                user_defined_function,
                *user_defined_function_args,
                **user_defined_function_kwargs,
            )

            if worker_index == 0 or not can_be_chunked(attributes):
                return result

            # This chunk has been extended on its left by `window` items, so the
            # rolling computation is correct even for its first items. These extra
            # items belong to the previous chunk: remove them from the result.
            return result.iloc[attributes["window"] :]

        @staticmethod
        def reduce(datas: Iterable[pd.Series], extra: Dict[str, Any]) -> pd.Series:
            return pd.concat(datas, copy=False)


class SeriesExpanding:
    """Parallelization of ``Series.expanding().apply(...)``.

    An expanding window always starts at the first item of the data, so a chunk cannot
    be computed independently from the ones before it. Each worker therefore receives
    every item from the beginning of the data up to the end of its own chunk, and only
    returns the part of the result which belongs to its chunk.
    """

    class Apply(DataType):
        @staticmethod
        def get_chunks(
            nb_workers: int, expanding: Expanding, **kwargs
        ) -> Iterator[pd.Series]:
            nb_items = len(expanding.obj)

            for chunk_ in chunk(nb_items, nb_workers):
                start = chunk_.start or 0
                yield expanding.obj.iloc[slice(0, chunk_.stop)], start

        @staticmethod
        def get_work_extra(data: Expanding) -> Dict[str, Any]:
            return {"attributes": get_window_attributes(data)}

        @staticmethod
        def work(
            data: Any,
            user_defined_function: Callable,
            user_defined_function_args: tuple,
            user_defined_function_kwargs: Dict[str, Any],
            extra: Dict[str, Any],
        ) -> pd.Series:
            attributes: Dict[str, Any] = extra["attributes"]
            values, start = data

            result = values.expanding(**attributes).apply(
                user_defined_function,
                *user_defined_function_args,
                **user_defined_function_kwargs,
            )

            return result.iloc[start:]

        @staticmethod
        def reduce(datas: Iterable[pd.Series], extra: Dict[str, Any]) -> pd.Series:
            return pd.concat(datas, copy=False)

